function buildCourseCertificate(id: (k: string) => string): SimpleElement[] {
  return [
    // Outer border frame
    { id: id('border-outer'), type: 'rect', x: 16, y: 16, width: 563, height: 810,
      style: { backgroundColor: 'transparent', borderWidth: 3, borderColor: '#1e3a5f', borderRadius: 4 } },
    { id: id('border-inner'), type: 'rect', x: 24, y: 24, width: 547, height: 794,
      style: { backgroundColor: 'transparent', borderWidth: 1, borderColor: '#93c5fd', borderRadius: 2 } },
    // Top accent band
    { id: id('top-band'), type: 'rect', x: 16, y: 16, width: 563, height: 8,
      style: { backgroundColor: '#1e3a5f', borderWidth: 0 } },
    { id: id('bot-band'), type: 'rect', x: 16, y: 818, width: 563, height: 8,
      style: { backgroundColor: '#1e3a5f', borderWidth: 0 } },

    // Header
    { id: id('issuer'), type: 'text', x: 60, y: 52, width: 475, height: 18,
      content: 'LEARNING INSTITUTE OF TECHNOLOGY', style: { fontSize: 11, color: '#1e3a5f', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('div1'), type: 'rect', x: 200, y: 76, width: 195, height: 2,
      style: { backgroundColor: '#bfdbfe', borderWidth: 0 } },
    { id: id('cert-title'), type: 'text', x: 60, y: 90, width: 475, height: 30,
      content: 'Certificate of Completion', style: { fontSize: 22, color: '#1e3a5f', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('awarded-to'), type: 'text', x: 60, y: 136, width: 475, height: 18,
      content: 'This is to certify that', style: { fontSize: 12, color: '#64748b', textAlign: 'center' } },

    // Recipient name
    { id: id('name-line'), type: 'rect', x: 100, y: 188, width: 395, height: 2,
      style: { backgroundColor: '#1e3a5f', borderWidth: 0 } },
    { id: id('name'), type: 'text', x: 60, y: 154, width: 475, height: 36,
      content: 'Alexandra J. Thompson', style: { fontSize: 28, color: '#0f172a', fontWeight: 'bold', textAlign: 'center' } },

    // Course details
    { id: id('has-completed'), type: 'text', x: 60, y: 200, width: 475, height: 18,
      content: 'has successfully completed the course', style: { fontSize: 12, color: '#64748b', textAlign: 'center' } },
    { id: id('course-name'), type: 'text', x: 60, y: 228, width: 475, height: 28,
      content: 'Advanced Data Science & Machine Learning', style: { fontSize: 20, color: '#1e3a5f', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('course-hours'), type: 'text', x: 60, y: 262, width: 475, height: 18,
      content: '40 hours of instruction  ·  18 May 2024', style: { fontSize: 11, color: '#64748b', textAlign: 'center' } },

    // Decorative divider
    { id: id('div2'), type: 'rect', x: 60, y: 292, width: 475, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },

    // Description
    { id: id('desc'), type: 'richtext', x: 80, y: 308, width: 435, height: 80,
      htmlContent: '<p style="text-align:center">This certificate recognises the successful completion of all required modules, assessments and practical projects. The holder has demonstrated proficiency in statistical modelling, neural networks, and applied machine learning techniques.</p>' },

    // Signature block
    { id: id('sig1-line'), type: 'rect', x: 80, y: 530, width: 160, height: 1,
      style: { backgroundColor: '#334155', borderWidth: 0 } },
    { id: id('sig1-name'), type: 'text', x: 80, y: 538, width: 160, height: 18,
      content: 'Dr. Sarah Mitchell', style: { fontSize: 11, color: '#0f172a', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('sig1-title'), type: 'text', x: 80, y: 558, width: 160, height: 14,
      content: 'Course Instructor', style: { fontSize: 9, color: '#64748b', textAlign: 'center' } },

    { id: id('sig2-line'), type: 'rect', x: 357, y: 530, width: 160, height: 1,
      style: { backgroundColor: '#334155', borderWidth: 0 } },
    { id: id('sig2-name'), type: 'text', x: 357, y: 538, width: 160, height: 18,
      content: 'Prof. James Wong', style: { fontSize: 11, color: '#0f172a', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('sig2-title'), type: 'text', x: 357, y: 558, width: 160, height: 14,
      content: 'Academic Director', style: { fontSize: 9, color: '#64748b', textAlign: 'center' } },

    // Credential ID + QR
    { id: id('cred-id'), type: 'text', x: 60, y: 600, width: 410, height: 14,
      content: 'Credential ID: LIT-DS-2024-8821  ·  Verify at: lit.edu/verify', style: { fontSize: 9, color: '#94a3b8', textAlign: 'center' } },
    { id: id('qr'), type: 'qrcode', x: 490, y: 520, width: 65, height: 65,
      qrValue: 'https://lit.edu/verify/LIT-DS-2024-8821' },
    { id: id('qr-lbl'), type: 'text', x: 490, y: 588, width: 65, height: 12,
      content: 'Verify', style: { fontSize: 7, color: '#94a3b8', textAlign: 'center' } },

    // Seal placeholder
    { id: id('seal'), type: 'circle', x: 258, y: 420, width: 80, height: 80,
      style: { backgroundColor: 'transparent', borderWidth: 2, borderColor: '#bfdbfe' } },
    { id: id('seal-txt'), type: 'text', x: 258, y: 452, width: 80, height: 16,
      content: 'OFFICIAL\nSEAL', style: { fontSize: 8, color: '#93c5fd', textAlign: 'center' } },
  ];
}

