function buildIncidentReport(id: (k: string) => string): SimpleElement[] {
  return [
    { id: id('hdr'), type: 'rect', x: 0, y: 0, width: 595, height: 64,
      style: { backgroundColor: '#7f1d1d', borderWidth: 0 } },
    { id: id('title'), type: 'text', x: 40, y: 12, width: 350, height: 22,
      content: 'IT / Security Incident Report', style: { fontSize: 16, color: '#ffffff', fontWeight: 'bold' } },
    { id: id('badge'), type: 'rect', x: 430, y: 14, width: 125, height: 28,
      style: { backgroundColor: '#dc2626', borderWidth: 0, borderRadius: 4 } },
    { id: id('badge-t'), type: 'text', x: 430, y: 14, width: 125, height: 28,
      content: 'SEVERITY: P1', style: { fontSize: 10, color: '#ffffff', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('sub'), type: 'text', x: 40, y: 38, width: 380, height: 14,
      content: 'Incident ID: INC-2026-0418  ·  Reported: 18 May 2026 14:22 UTC', style: { fontSize: 8.5, color: '#fca5a5' } },
    { id: id('info-bg'), type: 'rect', x: 40, y: 84, width: 515, height: 64,
      style: { backgroundColor: '#fef2f2', borderWidth: 1, borderColor: '#fecaca', borderRadius: 4 } },
    { id: id('info-t'), type: 'richtext', x: 52, y: 90, width: 491, height: 52,
      htmlContent: '<p><strong>Incident Summary:</strong> Unauthorised access detected on production API gateway at 14:18 UTC. Approximately 3,400 customer records may have been exposed. Service was isolated within 7 minutes of detection. Investigation ongoing.</p>' },
    { id: id('tbl-timeline'), type: 'table', x: 40, y: 170, width: 515, height: 172,
      style: { rows: 7, columns: 3, borderWidth: 1, borderColor: '#fecaca', cellPadding: 8 },
      headerRow: true, headerBgColor: '#7f1d1d', zebraEnabled: true, zebraColor: '#fff7f7',
      columnWidths: [120, 100, 295], columnAlignments: ['left', 'center', 'left'],
      cellData: [
        ['EVENT', 'TIME (UTC)', 'DESCRIPTION'],
        ['Initial Detection', '14:18', 'Anomalous API traffic detected by SIEM alerting'],
        ['Incident Declared', '14:22', 'On-call engineer escalated to P1; incident room opened'],
        ['Service Isolated', '14:25', 'API gateway taken offline; traffic rerouted'],
        ['Leadership Notified', '14:40', 'CTO, CISO, Legal and DPO briefed'],
        ['Root Cause Identified', '16:10', 'Compromised API key traced to third-party integration'],
        ['Service Restored', '17:45', 'Patched API key, service restored with enhanced monitoring'],
      ] },
    { id: id('rc-l'), type: 'text', x: 40, y: 364, width: 300, height: 14,
      content: 'Root Cause & Impact', style: { fontSize: 11, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('rc-t'), type: 'richtext', x: 40, y: 382, width: 515, height: 80,
      htmlContent: '<p><strong>Root Cause:</strong> An API key with excessive permissions was embedded in a third-party analytics SDK. A malicious actor used this key to make authenticated requests to the production API.</p><p><strong>Impact:</strong> An estimated 3,400 customer records (names, emails) may have been exposed. No payment data or passwords were accessed. DPA notification is required within 72 hours.</p>' },
    { id: id('actions-l'), type: 'text', x: 40, y: 484, width: 300, height: 14,
      content: 'Immediate Actions & Next Steps', style: { fontSize: 11, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('tbl-actions'), type: 'table', x: 40, y: 502, width: 515, height: 112,
      style: { rows: 4, columns: 4, borderWidth: 1, borderColor: '#e2e8f0', cellPadding: 8 },
      headerRow: true, headerBgColor: '#1e293b',
      columnWidths: [220, 90, 110, 95], columnAlignments: ['left', 'left', 'left', 'center'],
      cellData: [
        ['ACTION', 'OWNER', 'DUE DATE', 'STATUS'],
        ['Rotate all API keys; audit integrations', 'Security Team', '18 May', '✅ DONE'],
        ['Notify affected customers', 'DPO / Legal', '19 May', '🔄 IN PROGRESS'],
        ['DPA / Regulator notification', 'DPO', '21 May', '⬜ PENDING'],
        ['Post-incident review (PIR)', 'CISO', '25 May', '⬜ PENDING'],
      ] },
    { id: id('ft-line'), type: 'rect', x: 0, y: 800, width: 595, height: 1,
      style: { backgroundColor: '#fecaca', borderWidth: 0 } },
    { id: id('ft'), type: 'text', x: 0, y: 810, width: 595, height: 14,
      content: 'CONFIDENTIAL — INCIDENT REPORT INC-2026-0418  ·  IT & Security  ·  18 May 2026',
      style: { fontSize: 7.5, color: '#94a3b8', textAlign: 'center' } },
  ];
}

