function buildFreelanceAgreement(id: (k: string) => string): SimpleElement[] {
  return [
    { id: id('hdr-bg'), type: 'rect', x: 0, y: 0, width: 595, height: 60,
      style: { backgroundColor: '#0f172a', borderWidth: 0 } },
    { id: id('title'), type: 'text', x: 30, y: 18, width: 535, height: 24,
      content: 'FREELANCE SERVICE AGREEMENT', style: { fontSize: 15, color: '#ffffff', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('parties-lbl'), type: 'text', x: 30, y: 80, width: 495, height: 14,
      content: 'PARTIES', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('parties-div'), type: 'rect', x: 30, y: 96, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('parties'), type: 'richtext', x: 30, y: 102, width: 535, height: 72,
      htmlContent: '<p><strong>Service Provider ("Freelancer"):</strong> [Freelancer Name], [Address], [Email], [Phone]</p><p><strong>Client ("Company"):</strong> [Company Name], [Registered Address], [Company No.], represented by [Name, Title]</p><p>This Agreement is entered into as of <strong>[Date]</strong>.</p>' },
    { id: id('scope-lbl'), type: 'text', x: 30, y: 184, width: 495, height: 14,
      content: '1. SCOPE OF SERVICES', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('scope-div'), type: 'rect', x: 30, y: 200, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('scope'), type: 'richtext', x: 30, y: 206, width: 535, height: 72,
      htmlContent: '<p>The Freelancer agrees to provide the following services ("Services"):<br/><br/>[Detailed description of services to be provided, deliverables, format, and any specific technical requirements]<br/><br/>Any additional work outside this scope must be agreed in writing and may incur additional fees.</p>' },
    { id: id('payment-lbl'), type: 'text', x: 30, y: 288, width: 495, height: 14,
      content: '2. PAYMENT SCHEDULE', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('payment-div'), type: 'rect', x: 30, y: 304, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('payment-tbl'), type: 'table', x: 30, y: 310, width: 535, height: 86,
      style: { rows: 4, columns: 3, borderWidth: 1, borderColor: '#e2e8f0', cellPadding: 8 },
      headerRow: true, headerBgColor: '#1e293b',
      columnWidths: [210, 175, 150], columnAlignments: ['left', 'center', 'right'],
      cellData: [
        ['MILESTONE', 'DUE DATE', 'AMOUNT'],
        ['Project initiation (deposit)', 'On signing', '[Amount]'],
        ['Mid-project delivery', '[Date]', '[Amount]'],
        ['Final delivery & sign-off', 'On completion', '[Amount]'],
      ] },
    { id: id('ip-lbl'), type: 'text', x: 30, y: 408, width: 495, height: 14,
      content: '3. INTELLECTUAL PROPERTY OWNERSHIP', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('ip-div'), type: 'rect', x: 30, y: 424, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('ip'), type: 'richtext', x: 30, y: 430, width: 535, height: 60,
      htmlContent: '<p>Upon receipt of full payment, the Freelancer assigns to the Client all intellectual property rights (including copyright) in the deliverables. The Freelancer retains the right to display the work in their portfolio unless otherwise agreed in writing.</p>' },
    { id: id('termination-lbl'), type: 'text', x: 30, y: 502, width: 495, height: 14,
      content: '4. TERMINATION', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('termination-div'), type: 'rect', x: 30, y: 518, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('termination'), type: 'richtext', x: 30, y: 524, width: 535, height: 60,
      htmlContent: '<p>Either party may terminate this Agreement with [14] days written notice. In the event of termination, the Client shall pay for all work completed to date at the agreed rate. If terminated by the Client without cause after work has commenced, the deposit is non-refundable.</p>' },
    { id: id('confidentiality-lbl'), type: 'text', x: 30, y: 596, width: 495, height: 14,
      content: '5. CONFIDENTIALITY & GOVERNING LAW', style: { fontSize: 9, color: '#0f172a', fontWeight: 'bold' } },
    { id: id('confidentiality-div'), type: 'rect', x: 30, y: 612, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('confidentiality'), type: 'richtext', x: 30, y: 618, width: 535, height: 52,
      htmlContent: '<p>Both parties agree to keep confidential all non-public information. This Agreement shall be governed by the laws of [Jurisdiction]. Disputes shall be resolved by negotiation or, failing that, mediation.</p>' },
    { id: id('sig-client'), type: 'signature', x: 30, y: 692, width: 230, height: 70,
      signatureLabel: 'Client Signature & Date' },
    { id: id('sig-freelancer'), type: 'signature', x: 335, y: 692, width: 230, height: 70,
      signatureLabel: 'Freelancer Signature & Date' },
  ];
}

