function buildPartnershipAgreement(id: (k: string) => string): SimpleElement[] {
  return [
    { id: id('hdr-bg'), type: 'rect', x: 0, y: 0, width: 595, height: 60,
      style: { backgroundColor: '#713f12', borderWidth: 0 } },
    { id: id('title'), type: 'text', x: 30, y: 16, width: 535, height: 28,
      content: 'PARTNERSHIP AGREEMENT', style: { fontSize: 14, color: '#ffffff', fontWeight: 'bold', textAlign: 'center' } },
    { id: id('parties'), type: 'richtext', x: 30, y: 76, width: 535, height: 66,
      htmlContent: '<p>This Partnership Agreement is made on <strong>[Date]</strong> between the following partners who agree to carry on business as a general partnership under the name <strong>"[Partnership Name]"</strong>:</p><ul><li><strong>Partner A:</strong> [Name], [Address] — [Contribution: £Amount / Skill set]</li><li><strong>Partner B:</strong> [Name], [Address] — [Contribution: £Amount / Skill set]</li></ul>' },
    { id: id('profit-lbl'), type: 'text', x: 30, y: 152, width: 495, height: 14,
      content: '1. PROFIT & LOSS SHARING', style: { fontSize: 9, color: '#713f12', fontWeight: 'bold' } },
    { id: id('profit-div'), type: 'rect', x: 30, y: 168, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('profit-tbl'), type: 'table', x: 30, y: 174, width: 535, height: 86,
      style: { rows: 4, columns: 3, borderWidth: 1, borderColor: '#e2e8f0', cellPadding: 10 },
      headerRow: true, headerBgColor: '#78350f',
      columnWidths: [200, 167, 168], columnAlignments: ['left', 'center', 'center'],
      cellData: [
        ['PARTNER', 'PROFIT SHARE', 'LOSS SHARE'],
        ['Partner A – [Name]', '[50%]', '[50%]'],
        ['Partner B – [Name]', '[50%]', '[50%]'],
        ['TOTAL', '100%', '100%'],
      ] },
    { id: id('decision-lbl'), type: 'text', x: 30, y: 272, width: 495, height: 14,
      content: '2. DECISION-MAKING', style: { fontSize: 9, color: '#713f12', fontWeight: 'bold' } },
    { id: id('decision-div'), type: 'rect', x: 30, y: 288, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('decision'), type: 'richtext', x: 30, y: 294, width: 535, height: 60,
      htmlContent: '<p>Routine decisions may be made by either partner independently. Major decisions (capital expenditure over £[Amount], entering new contracts, hiring staff, taking on debt) require unanimous written agreement of all partners. Monthly management meetings shall be held.</p>' },
    { id: id('banking-lbl'), type: 'text', x: 30, y: 366, width: 495, height: 14,
      content: '3. BANKING & ACCOUNTS', style: { fontSize: 9, color: '#713f12', fontWeight: 'bold' } },
    { id: id('banking-div'), type: 'rect', x: 30, y: 382, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('banking'), type: 'richtext', x: 30, y: 388, width: 535, height: 52,
      htmlContent: '<p>A partnership bank account shall be maintained requiring dual signatories for transactions over £[Amount]. Financial accounts shall be prepared annually by [Accountant]. Each partner shall receive monthly management accounts within 15 days of month end.</p>' },
    { id: id('dissolution-lbl'), type: 'text', x: 30, y: 452, width: 495, height: 14,
      content: '4. DISSOLUTION CLAUSE', style: { fontSize: 9, color: '#713f12', fontWeight: 'bold' } },
    { id: id('dissolution-div'), type: 'rect', x: 30, y: 468, width: 535, height: 1,
      style: { backgroundColor: '#e2e8f0', borderWidth: 0 } },
    { id: id('dissolution'), type: 'richtext', x: 30, y: 474, width: 535, height: 66,
      htmlContent: '<p>The Partnership may be dissolved by: (a) unanimous written agreement of all partners; (b) death or incapacity of a partner; (c) material breach of this Agreement. Upon dissolution, assets shall first be used to settle liabilities, with remaining assets distributed per profit share ratios. Each partner has a first right of refusal to purchase the other\'s interest.</p>' },
    { id: id('sig-a'), type: 'signature', x: 30, y: 562, width: 230, height: 70,
      signatureLabel: 'Partner A Signature & Date' },
    { id: id('sig-b'), type: 'signature', x: 335, y: 562, width: 230, height: 70,
      signatureLabel: 'Partner B Signature & Date' },
  ];
}

